import{useEffect,useRef}from'react';import gsap from'gsap';
const areas=[['Planning and governance','We help county teams and residents make plans that are clear, fair and possible to deliver.'],['Urban livelihoods','We support work that protects incomes while making cities safer and easier to use.'],['Housing and services','We use mapping and local evidence to guide better choices on homes, infrastructure and safety.'],['Gender, equity & inclusion','We ask who is included, who is left out and what must change before decisions are made.']];
export default function Mission(){const ref=useRef(null);useEffect(()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const c=gsap.context(()=>gsap.fromTo('.mission-copy',{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0% 0)',duration:1,scrollTrigger:{trigger:ref.current,start:'top 72%',once:true}}),ref);return()=>c.revert()},[]);return <section id="mission" ref={ref} className="py-20 sm:py-28"><div className="frame"><div className="grid overflow-hidden rounded-[12px] bg-ink text-white lg:grid-cols-2"><div className="media-frame min-h-[320px] sm:min-h-[420px]"><img src="/images/mission-planning.jpg" alt="People working together around a plan" className="h-full w-full object-cover"/></div><div className="mission-copy p-8 sm:p-14"><p className="font-display text-sm font-bold uppercase tracking-[.14em] text-plot">Our mission</p><h2 className="display mt-5 text-4xl font-extrabold leading-[1.02] sm:text-5xl">Planning decisions should serve people first.</h2><p className="mt-7 text-lg leading-relaxed text-white/85">CSPARK brings research, advocacy and practical support together so communities can have a real voice in decisions that affect their homes, work and future.</p></div></div><div className="mt-3 grid gap-3 md:grid-cols-2">{areas.map(([title,copy])=><article className="rounded-[12px] border border-line bg-white p-8 shadow-sm sm:p-10" key={title}><h3 className="display text-3xl font-bold">{title}</h3><p className="mt-4 max-w-md leading-relaxed text-map">{copy}</p><a href="#contact" className="action-link mt-7">Explore <span>→</span></a></article>)}</div></div></section>}
