import { Link } from 'react-router-dom';

export default function Footer() {
  return (
    <footer id="contact" className="relative isolate overflow-hidden bg-ink text-white">
      <div className="absolute inset-0 -z-10">
        <img src="/images/footer-image.jpg" alt="" className="h-full w-full object-cover opacity-20" />
        <div className="absolute inset-0 bg-gradient-to-r from-ink via-ink/90 to-ink/70" />
      </div>

      <section className="frame grid gap-10 border-b border-white/20 py-20 lg:grid-cols-[1fr_auto]">
        <div>
          <p className="font-display text-sm font-bold uppercase tracking-[.13em] text-plot">Partner with us</p>
          <h2 className="display mt-4 max-w-3xl text-5xl font-extrabold leading-tight">
            Let's plan for places where people can thrive.
          </h2>
          <p className="mt-6 max-w-xl text-lg leading-relaxed text-white/75">
            Talk to us about research, planning support or a partnership.
          </p>
        </div>
        <a href="mailto:info@cspark.org" className="button-plot self-end">
          Email CSPARK <span>→</span>
        </a>
      </section>

      <div className="frame grid gap-10 py-14 md:grid-cols-4">
        <div>
          <b className="font-display text-2xl">CSPARK</b>
          <p className="mt-3 text-sm leading-relaxed text-white/60">
            Centre for Spatial Planning Advocacy and Research in Kenya.
          </p>
        </div>
        <div>
          <h3 className="font-display font-bold text-plot">Contact</h3>
          <p className="mt-4 leading-relaxed text-white/70">
            P. O. Box 7444 - 40100 Kisumu<br />Kisumu, Kenya<br />+254 794055805<br />info@cspark.org
          </p>
        </div>
        <div>
          <h3 className="font-display font-bold text-plot">Explore</h3>
          <div className="mt-4 grid gap-2 text-white/70">
            <Link to="/about">About</Link>
            <Link to="/what-we-do">What we do</Link>
            <Link to="/#projects">Projects</Link>
          </div>
        </div>
        <div>
          <h3 className="font-display font-bold text-plot">Resources</h3>
          <div className="mt-4 grid gap-2 text-white/70">
            <Link to="/#governance">Governance</Link>
            <Link to="/#top">Privacy policy</Link>
          </div>
        </div>
      </div>

      <div className="border-t border-white/20">
        <div className="frame py-5 text-sm text-white/50">
          &copy; {new Date().getFullYear()} CSPARK
        </div>
      </div>
    </footer>
  );
}