import{useEffect,useRef}from'react';import gsap from'gsap';
const figures=[['11+','Counties'],['20+','Studies and plans'],['6','Areas of work'],['5+','Years']];
export default function Stats(){const ref=useRef(null);useEffect(()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const c=gsap.context(()=>gsap.fromTo('.glance-item',{y:35,opacity:0},{y:0,opacity:1,stagger:.11,duration:.65,scrollTrigger:{trigger:ref.current,start:'top 78%',once:true}}),ref);return()=>c.revert()},[]);return <section id="about" ref={ref} className="bg-paper py-20 sm:py-24"><div className="frame"><div className="grid items-center gap-8 rounded-[12px] bg-white p-6 shadow-sm lg:grid-cols-[.9fr_.65fr_1fr] lg:p-9"><div><p className="mono-label">CSPARK at a glance</p><h2 className="display mt-4 text-4xl font-extrabold leading-tight">A growing record of local work.</h2><p className="mt-4 max-w-md leading-relaxed">Every number stands for a relationship, a place and a practical outcome.</p></div><div className="media-frame aspect-[4/5] max-h-[390px] rounded-[10px]"><img src="/images/track-record.jpg" alt="Kenyan community member" className="h-full w-full object-cover"/></div><div className="grid grid-cols-2 gap-px overflow-hidden rounded-[10px] bg-line">{figures.map(([n,label])=><div className="glance-item bg-paper p-5" key={label}><b className="font-display text-5xl font-extrabold text-plot">{n}</b><p className="mt-2 text-sm leading-snug">{label}</p></div>)}</div></div></div></section>}
